R=/tmp/probe/targets-walk
cat > $R/lib.sh <<'EOF'
R=/tmp/probe/targets-walk
O=$R/out
# dirty(path, pkg): writes a file whose imports are unsorted
dirty(){ mkdir -p "$(dirname "$1")"; printf 'package %s

import (
	"os"
	"fmt"
)

var _ = fmt.Sprint(os.Args)
' "$2" > "$1"; }
# clean(path,pkg): already-sorted
clean(){ mkdir -p "$(dirname "$1")"; printf 'package %s

import (
	"fmt"
	"os"
)

var _ = fmt.Sprint(os.Args)
' "$2" > "$1"; }
# changed(root): list files (relative to root) that are now sorted (i.e. were processed)
changed(){ ( cd "$1" && find . -name '*.go' | LC_ALL=C sort | while read -r f; do
   if grep -q -A1 '^import (' "$f" 2>/dev/null && sed -n '4p' "$f" | grep -q '"fmt"'; then echo "MODIFIED $f"; else echo "untouched $f"; fi
 done ) }
EOF
echo ok
